<main id="scanner" class="fixed inset-0 overflow-hidden bg-black">
  <video id="scanner-video" class="h-full w-full object-cover" autoplay muted playsinline></video>
  <canvas id="face-overlay" class="pointer-events-none absolute inset-0 h-full w-full"></canvas>
  <canvas id="scanner-canvas" class="hidden"></canvas>
  <div class="absolute bottom-5 left-5 rounded-xl bg-black/45 px-4 py-3 text-sm font-bold uppercase tracking-widest text-white backdrop-blur">Live attendance scanner</div>
  <div id="scanner-action-label" class="absolute bottom-20 left-5 hidden rounded-xl bg-black/45 px-4 py-2 text-xs font-bold uppercase tracking-widest backdrop-blur"></div>
