  <div id="scanner-controls" class="absolute inset-x-0 bottom-5 z-10 flex justify-center px-5"><div class="flex items-center gap-3 rounded-2xl bg-black/55 p-3 shadow-2xl backdrop-blur"><button id="scan-toggle" class="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-3 font-bold text-white hover:bg-blue-700"><span aria-hidden="true">▶</span> Start scanner</button><button id="manual-attendance" class="inline-flex items-center gap-2 rounded-xl bg-white/15 px-4 py-3 font-bold text-white hover:bg-white/25"><span aria-hidden="true">✎</span> Manual attendance</button></div></div>
  <button id="back-button" class="absolute left-5 top-5 z-20 rounded-xl border border-white/30 bg-black/30 px-4 py-3 font-bold text-white backdrop-blur hover:bg-black/55"><span aria-hidden="true">←</span> Back</button>

  <div id="scan-type-modal" class="absolute inset-0 z-30 hidden items-center justify-center bg-black/70 p-5"><div class="w-full max-w-md rounded-2xl bg-white p-6 text-slate-800 shadow-2xl"><h1 class="text-xl font-black">Choose attendance action</h1><p class="mt-2 text-sm text-slate-500">Select what the live camera should record.</p><div class="mt-6 grid gap-3 sm:grid-cols-2"><button type="button" data-scan-type="time_in" class="rounded-xl bg-emerald-600 px-4 py-4 text-left font-bold text-white hover:bg-emerald-700"><span class="block text-lg">Time in</span><span class="mt-1 block text-xs font-medium text-emerald-100">Record each student's arrival</span></button><button type="button" data-scan-type="time_out" class="rounded-xl bg-amber-500 px-4 py-4 text-left font-bold text-white hover:bg-amber-600"><span class="block text-lg">Time out</span><span class="mt-1 block text-xs font-medium text-amber-50">Record each student's departure</span></button></div><button id="cancel-scan-type" type="button" class="mt-4 w-full rounded-xl border border-slate-300 px-4 py-3 font-bold text-slate-700 hover:bg-slate-50">Cancel</button></div></div>
  <div id="manual-modal" class="absolute inset-0 z-30 hidden items-center justify-center bg-black/70 p-5"><div class="w-full max-w-sm rounded-2xl bg-white p-6 text-slate-800 shadow-2xl"><div class="flex items-start justify-between gap-3"><div><h1 class="text-xl font-black">Manual attendance</h1><p class="mt-1 text-sm text-slate-500">Search for a student by name.</p></div><button id="close-manual" class="rounded-lg px-2 text-2xl text-slate-400 hover:text-slate-700" aria-label="Close">&times;</button></div><div class="relative mt-5"><input id="manual-student-name" class="w-full rounded-xl border border-slate-300 px-4 py-3" placeholder="Student name" autocomplete="off"><div id="manual-options" class="absolute inset-x-0 z-10 mt-2 hidden max-h-52 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1 shadow-xl"></div></div><p id="manual-message" class="mt-3 text-sm text-slate-500"></p><div id="manual-result" class="mt-5 hidden text-center"><img id="manual-image" class="mx-auto aspect-square w-32 rounded-2xl object-cover" alt="Student"><p id="manual-name" class="mt-3 text-lg font-black"></p><p id="manual-id-label" class="text-sm text-slate-500"></p><button id="mark-present" class="mt-5 w-full rounded-xl bg-emerald-600 px-4 py-3 font-bold text-white hover:bg-emerald-700">Record time in</button></div></div></div>
  <div id="exit-modal" class="absolute inset-0 z-40 hidden items-center justify-center bg-black/70 p-5"><form action="scanner-exit.php" method="post" class="w-full max-w-sm rounded-2xl bg-white p-6 text-slate-800 shadow-2xl"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><h1 class="text-xl font-black">Exit scanner</h1><p class="mt-2 text-sm text-slate-500">Enter the administrator password to return to the dashboard.</p><label class="mt-5 block text-sm font-bold">Password<input id="exit-password" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3" type="password" name="password" required></label><div class="mt-5 flex gap-3"><button class="flex-1 rounded-xl bg-blue-600 px-4 py-3 font-bold text-white">Confirm exit</button><button id="cancel-exit" type="button" class="rounded-xl border border-slate-300 px-4 py-3 font-bold">Cancel</button></div></form></div>
</main>
<script>
const video=document.getElementById('scanner-video'),canvas=document.getElementById('scanner-canvas'),overlay=document.getElementById('face-overlay'),toggle=document.getElementById('scan-toggle'),controls=document.getElementById('scanner-controls'),actionLabel=document.getElementById('scanner-action-label'),requestedCamera=<?= json_encode($requestedCamera) ?>,csrfToken=<?= json_encode($_SESSION['csrf_token']) ?>;
let stream=null,timer=null,running=false,scanType=null,hideTimer=null,manualStudent=null,searchTimer=null;
const recentlyShown=new Map(),unknownTracks=[];
function showControls(){controls.classList.remove('scanner-controls-hidden');clearTimeout(hideTimer);hideTimer=setTimeout(()=>controls.classList.add('scanner-controls-hidden'),3000)}
function renderToggle(){toggle.className='inline-flex items-center gap-2 rounded-xl px-4 py-3 font-bold text-white '+(running?'bg-red-600 hover:bg-red-700':'bg-blue-600 hover:bg-blue-700');toggle.innerHTML=running?'<span aria-hidden="true">■</span> Stop scanner':'<span aria-hidden="true">▶</span> Start scanner'}
function setActionLabel(type){if(!type){actionLabel.classList.add('hidden');actionLabel.textContent='';return}actionLabel.textContent='Recording '+type.replace('_',' ');actionLabel.className='absolute bottom-20 left-5 rounded-xl bg-black/45 px-4 py-2 text-xs font-bold uppercase tracking-widest backdrop-blur '+(type==='time_out'?'text-amber-200':'text-emerald-200')}
function stop(){running=false;scanType=null;clearTimeout(timer);if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}video.srcObject=null;overlay.getContext('2d').clearRect(0,0,overlay.width,overlay.height);setActionLabel(null);renderToggle()}
async function start(type){stop();try{const deviceId=requestedCamera||localStorage.getItem('attendance-camera')||'';stream=await navigator.mediaDevices.getUserMedia({video:{deviceId:deviceId?{exact:deviceId}:undefined,width:{ideal:1280},height:{ideal:720},frameRate:{ideal:30}},audio:false});video.srcObject=stream;await video.play();scanType=type;running=true;setActionLabel(type);renderToggle();scan()}catch(error){console.error('Unable to open the selected camera.',error);stop()}}
function drawFaces(faces){const width=video.clientWidth,height=video.clientHeight,ctx=overlay.getContext('2d');overlay.width=width;overlay.height=height;ctx.clearRect(0,0,width,height);if(!faces?.length||!video.videoWidth)return;const scale=Math.max(width/video.videoWidth,height/video.videoHeight),offsetX=(width-video.videoWidth*scale)/2,offsetY=(height-video.videoHeight*scale)/2;ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.shadowColor='rgba(0,0,0,.75)';ctx.shadowBlur=5;faces.forEach(face=>{const box=face.box;if(!box)return;const x=box.left/canvas.width*video.videoWidth*scale+offsetX,y=box.top/canvas.height*video.videoHeight*scale+offsetY,w=(box.right-box.left)/canvas.width*video.videoWidth*scale,h=(box.bottom-box.top)/canvas.height*video.videoHeight*scale,corner=Math.min(26,w/3,h/3);ctx.beginPath();ctx.moveTo(x+corner,y);ctx.lineTo(x,y);ctx.lineTo(x,y+corner);ctx.moveTo(x+w-corner,y);ctx.lineTo(x+w,y);ctx.lineTo(x+w,y+corner);ctx.moveTo(x,y+h-corner);ctx.lineTo(x,y+h);ctx.lineTo(x+corner,y+h);ctx.moveTo(x+w-corner,y+h);ctx.lineTo(x+w,y+h);ctx.lineTo(x+w,y+h-corner);ctx.stroke()});ctx.shadowBlur=0}
function showMatches(matches){const stack=document.getElementById('detected-stack'),now=Date.now();matches.forEach(match=>{const student=match.student||{},id=String(student.STUDENT_ID||''),state=match.action||scanType||'time_in',last=recentlyShown.get(id);if(!id||(last&&last.state===state&&last.until>now))return;recentlyShown.set(id,{state,until:now+5000});const card=document.createElement('div');card.className='flex w-72 translate-y-2 items-center gap-3 rounded-2xl bg-black/75 p-3 text-left text-white opacity-0 shadow-2xl ring-1 ring-white/20 backdrop-blur transition-all duration-500';const image=document.createElement('img');image.className='h-12 w-12 rounded-xl object-cover';image.src='../'+(student.IMAGE_PATH||'image/student-preview.png');image.alt='';const text=document.createElement('div');text.innerHTML='<p class="text-xs font-bold uppercase tracking-widest text-blue-200"></p><p class="mt-1 text-base font-black"></p><p class="mt-0.5 text-xs text-slate-200"></p>';text.querySelector('p:first-child').textContent=match.manual?'Manual attendance':(match.action==='time_out'?'Time out face detected':'Time in face detected');text.querySelector('p:nth-child(2)').textContent=student.STUDENT_NAME||'Student';text.querySelector('p:nth-child(3)').textContent=match.message||(match.logged?'Attendance recorded':'Already recorded');card.append(image,text);stack.appendChild(card);requestAnimationFrame(()=>card.classList.remove('translate-y-2','opacity-0'));setTimeout(()=>card.classList.add('translate-y-2','opacity-0'),4000);setTimeout(()=>card.remove(),4600)})}
function overlap(a,b){const left=Math.max(a.left,b.left),top=Math.max(a.top,b.top),right=Math.min(a.right,b.right),bottom=Math.min(a.bottom,b.bottom),intersection=Math.max(0,right-left)*Math.max(0,bottom-top),areaA=Math.max(1,(a.right-a.left)*(a.bottom-a.top)),areaB=Math.max(1,(b.right-b.left)*(b.bottom-b.top));return intersection/(areaA+areaB-intersection)}
async function saveUnknownFace(box,frame){const form=new FormData();form.append('csrf_token',csrfToken);form.append('frame',frame);form.append('box',JSON.stringify(box));try{await fetch('log-unregistered.php',{method:'POST',body:form})}catch(error){console.error('Could not save unregistered face.',error)}}
function handleUnknownFaces(faces,frame){const now=Date.now();for(let index=unknownTracks.length-1;index>=0;index--)if(now-unknownTracks[index].lastSeen>3000)unknownTracks.splice(index,1);faces.forEach(face=>{const box=face.box;if(!box)return;let track=unknownTracks.find(item=>overlap(item.box,box)>=.35);if(!track){unknownTracks.push({box,lastSeen:now,firstSeen:now,hits:1,saved:false});return}track.box=box;track.lastSeen=now;track.hits++;if(!track.saved&&track.hits>=7&&now-track.firstSeen>=1200){track.saved=true;saveUnknownFace(box,frame)}})}
async function scan(){if(!running||!stream||video.readyState<2)return;const scale=Math.min(1,560/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d',{alpha:false}).drawImage(video,0,0,canvas.width,canvas.height);const frame=canvas.toDataURL('image/jpeg',.65);try{const form=new FormData();form.append('frame',frame);form.append('scan_type',scanType);const response=await fetch('scan-match.php',{method:'POST',body:form});const result=await response.json();drawFaces(result.faces||[]);handleUnknownFaces(result.unregistered||[],frame);if(result.matches?.length)showMatches(result.matches)}catch(error){console.error('Recognition service unavailable.',error)}finally{if(running)timer=setTimeout(scan,180)}}
async function selectStudent(id){const message=document.getElementById('manual-message'),result=document.getElementById('manual-result'),options=document.getElementById('manual-options');options.classList.add('hidden');message.textContent='Loading student…';result.classList.add('hidden');const response=await fetch('manual-student.php?id='+encodeURIComponent(id));const data=await response.json();if(!data.student){manualStudent=null;message.textContent=data.message||'Student not found.';return}manualStudent=data.student;document.getElementById('manual-image').src='../'+(manualStudent.IMAGE_PATH||'image/student-preview.png');document.getElementById('manual-name').textContent=manualStudent.STUDENT_NAME;document.getElementById('manual-id-label').textContent=manualStudent.STUDENT_ID;const button=document.getElementById('mark-present');button.textContent=data.already_logged?'Time in already recorded':'Record time in';button.disabled=data.already_logged;button.className='mt-5 w-full rounded-xl px-4 py-3 font-bold text-white '+(data.already_logged?'bg-slate-400':'bg-emerald-600 hover:bg-emerald-700');message.textContent='';result.classList.remove('hidden')}
function searchStudents(){const name=document.getElementById('manual-student-name').value.trim(),options=document.getElementById('manual-options');clearTimeout(searchTimer);if(name.length<2){options.classList.add('hidden');return}searchTimer=setTimeout(async()=>{const response=await fetch('manual-students-search.php?q='+encodeURIComponent(name));const data=await response.json();options.innerHTML='';(data.students||[]).forEach(student=>{const button=document.createElement('button');button.type='button';button.className='flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-slate-100';button.textContent=student.STUDENT_NAME+' · '+student.STUDENT_ID;button.onclick=()=>{document.getElementById('manual-student-name').value=student.STUDENT_NAME;selectStudent(student.STUDENT_ID)};options.appendChild(button)});options.classList.toggle('hidden',!options.children.length)},250)}
async function markPresent(){if(!manualStudent)return;const form=new FormData();form.append('student_id',manualStudent.STUDENT_ID);form.append('csrf_token',csrfToken);const response=await fetch('manual-attendance-save.php',{method:'POST',body:form});const data=await response.json();if(data.student){document.getElementById('manual-modal').classList.replace('flex','hidden');showMatches([{student:data.student,logged:data.logged,action:data.action,message:data.message,manual:true}])}else document.getElementById('manual-message').textContent=data.message||'Could not record attendance.'}
toggle.onclick=()=>running?stop():document.getElementById('scan-type-modal').classList.replace('hidden','flex');
document.querySelectorAll('[data-scan-type]').forEach(button=>button.onclick=()=>{document.getElementById('scan-type-modal').classList.replace('flex','hidden');start(button.dataset.scanType)});
document.getElementById('cancel-scan-type').onclick=()=>document.getElementById('scan-type-modal').classList.replace('flex','hidden');
document.getElementById('manual-attendance').onclick=()=>{document.getElementById('manual-modal').classList.replace('hidden','flex');setTimeout(()=>document.getElementById('manual-student-name').focus(),0);showControls()};
document.getElementById('close-manual').onclick=()=>document.getElementById('manual-modal').classList.replace('flex','hidden');document.getElementById('manual-student-name').oninput=searchStudents;document.getElementById('mark-present').onclick=markPresent;
document.getElementById('back-button').onclick=()=>{document.getElementById('exit-modal').classList.replace('hidden','flex');setTimeout(()=>document.getElementById('exit-password').focus(),0)};document.getElementById('cancel-exit').onclick=()=>document.getElementById('exit-modal').classList.replace('flex','hidden');
document.addEventListener('mousemove',showControls);document.addEventListener('touchstart',showControls,{passive:true});window.addEventListener('beforeunload',stop);renderToggle();showControls();
</script>
</body></html>
